-- Sample app schema for Oracle Database 19c and later (SAMPLE_DB=oracle; Oracle Database Free in
-- containers). 19c has no CREATE TABLE IF NOT EXISTS: each object is created by a PL/SQL block that
-- ignores ORA-00955 (name already used) and ORA-01408 (column list already indexed). A PL/SQL block
-- starts with BEGIN and ends with a line holding only '/', as in SQL*Plus; other statements end
-- with ';' at the end of a line (ShopSchema). Data is generated by ShopSchema when the tables are
-- empty.
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE customers (id NUMBER(19) PRIMARY KEY, name VARCHAR2(100) NOT NULL, email VARCHAR2(200) NOT NULL)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE products (id NUMBER(19) PRIMARY KEY, name VARCHAR2(100) NOT NULL, price NUMBER(12, 2) NOT NULL)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE orders (id NUMBER(19) PRIMARY KEY, customer_id NUMBER(19) NOT NULL, status VARCHAR2(20) NOT NULL, amount NUMBER(12, 2) NOT NULL, created_at TIMESTAMP NOT NULL)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE order_items (id NUMBER(19) PRIMARY KEY, order_id NUMBER(19) NOT NULL, product_id NUMBER(19) NOT NULL, quantity NUMBER(10) NOT NULL)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE INDEX order_items_order_idx ON order_items (order_id)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE NOT IN (-955, -1408) THEN
      RAISE;
    END IF;
END;
/
BEGIN
  EXECUTE IMMEDIATE 'CREATE TABLE audit_log (id NUMBER(19) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, message VARCHAR2(500) NOT NULL, created_at TIMESTAMP NOT NULL)';
EXCEPTION
  WHEN OTHERS THEN
    IF SQLCODE != -955 THEN
      RAISE;
    END IF;
END;
/
